{"command": "cd /workspace/work && cat > compose.py <<'EOF'
"""Compose the keygen tune: builds a linear timeline, slices to patterns, emits FT2 batch JSON."""
import json, math

# ---------------------------------------------------------------- basics
SPEED, BPM = 6, 150            # row = 0.1 s, 64-row pattern = 4 bars
ROWS = 64
NCH = 14
KICK, SNARE, HAT, OHAT, CLAP, CRASH, RISER, BELL, BASS, PLUCK, LEADPWM, PAD, LEADSAW, CHIP = range(1, 15)
INSTR_FILES = {KICK:'kick', SNARE:'snare', HAT:'hat', OHAT:'open_hat', CLAP:'clap', CRASH:'crash',
               RISER:'riser', BELL:'bell', BASS:'bass', PLUCK:'pluck', LEADPWM:'lead_pwm', PAD:'pad',
               LEADSAW:'lead_saw', CHIP:'chip_square'}
# channel map
cK, cS, cH, cC, cB, cA, cQ, cP1, cP2, cL, cE, cHm, cX, cA2 = range(14)

MIX = 1.0   # global scale applied to sample volumes
INSTR_VOL = {KICK:64, SNARE:50, HAT:34, OHAT:36, CLAP:36, CRASH:40, RISER:40, BELL:44, BASS:54,
             PLUCK:40, LEADPWM:46, PAD:24, LEADSAW:28, CHIP:22}
INSTR_PAN = {KICK:128, SNARE:128, HAT:150, OHAT:150, CLAP:100, CRASH:128, RISER:128, BELL:150, BASS:128,
             PLUCK:92, LEADPWM:118, PAD:128, LEADSAW:76, CHIP:140}

NAMES = ['C-','C#','D-','D#','E-','F-','F#','G-','G#','A-','A#','B-']
def N(s):
    """'F#5' or 'F#-5'-> XM note number (C-0 = 1)."""
    s = s.replace('-', '') if len(s) == 4 else s
    pc = NAMES.index(s[:2] if s[1] == '#' else s[0] + '-')
    octv = int(s[-1])
    return octv*12 + pc + 1
def NN(pc, octv): return octv*12 + pc + 1
OFF = 97

CHORDS = {   # name: (root pc, [intervals])
    'Em': (4, [0, 3, 7]), 'C': (0, [0, 4, 7]), 'G': (7, [0, 4, 7]), 'D': (2, [0, 4, 7]),
    'B': (11, [0, 4, 7]), 'Am': (9, [0, 3, 7]), 'Bm': (11, [0, 3, 7]),
}
def tones(ch):
    r, iv = CHORDS[ch]; return [(r + i) % 12 for i in iv]

song = {c: {} for c in range(NCH)}
def put(ch, row, note=None, inst=None, vol=None, fx=None, param=None):
    cell = song[ch].setdefault(row, {})
    if note is not None: cell['note'] = note
    if inst is not None: cell['instrument'] = inst
    if vol is not None: cell['volume'] = 0x10 + max(0, min(64, int(round(vol))))
    if fx is not None: cell['effect'] = fx; cell['effect_param'] = param or 0

def hit(ch, row, inst, vol=64, pan=None):
    put(ch, row, inst=inst, note=N('C-4'), vol=vol)
    if pan is not None: put(ch, row, fx=8, param=pan)

# ---------------------------------------------------------------- sections
PROG_V = ['Em', 'C', 'G', 'D']
PROG_K = ['C', 'D', 'Em', 'B']
SECTIONS = [  # (name, progression)
    ('intro1', PROG_V), ('intro2', PROG_V), ('verseA', PROG_V), ('verseB', PROG_V),
    ('chorusA', PROG_K), ('chorusB', PROG_K), ('break', PROG_V), ('chorusA2', PROG_K), ('chorusC', PROG_K)]
RESTART = 1

def parse_mel(bars):
    """list of bar strings 'E5:3 r:2 ...' -> list of (row, note, dur) within section."""
    out = []
    for b, s in enumerate(bars):
        r = 0
        for tok in s.split():
            nm, d = tok.split(':'); d = int(d)
            if nm != 'r': out.append((b*16 + r, N(nm), d))
            r += d
        assert r == 16, (b, s, r)
    return out

VERSE1 = ["E5:3 B4:1 E5:2 G5:2 F#5:4 E5:2 D5:2",
          "C5:4 E5:2 G5:2 A5:3 G5:1 E5:4",
          "D5:3 G5:1 B5:2 A5:2 G5:4 F#5:2 D5:2",
          "F#5:4 A5:2 F#5:2 E5:6 r:2"]
VERSE2 = ["E5:3 B4:1 E5:2 G5:2 F#5:4 E5:2 D5:2",
          "C5:4 E5:2 G5:2 A5:3 G5:1 E5:4",
          "G5:2 A5:2 B5:4 A5:2 G5:2 A5:4",
          "B5:4 A5:2 F#5:2 D5:4 E5:2 F#5:2"]
CHORUS_A = ["G5:2 E5:2 C5:2 E5:2 G5:4 A5:2 G5:2",
            "A5:2 F#5:2 D5:2 F#5:2 A5:4 B5:2 A5:2",
            "B5:3 G5:1 E5:4 G5:2 A5:2 B5:4",
            "F#5:4 D#5:2 B4:2 D#5:2 F#5:2 B5:4"]
CHORUS_B = [CHORUS_A[0], CHORUS_A[1],
            "E5:2 G5:2 B5:4 A5:2 G5:2 F#5:4",
            "D#5:4 F#5:4 B4:8"]
CHORUS_C = [CHORUS_A[0], CHORUS_A[1], CHORUS_A[2],
            "F#5:4 D#5:2 F#5:2 B5:4 r:4"]
INTRO_BELL = ["B4:6 E5:4 G5:6", "G5:6 E5:4 C5:6", "D5:6 G5:4 B5:6", "A5:6 F#5:4 D5:4 E5:2"]
BREAK_BELL = ["E5:6 B4:4 G5:6", "G5:6 E5:4 C5:6", "B5:6 G5:4 D5:6", "F#5:6 A5:4 D5:6"]

def chord_tone_below(note, chord, min_gap=3):
    pcs = tones(chord)
    n = note - min_gap
    while (n - 1) % 12 not in pcs: n -= 1
    return n

def lead_line(base, mel, chord_of_row, vol=64, echo=True, harmony=False, vib=True):
    ends = {}
    for i, (r, note, d) in enumerate(mel):
        row = base + r
        put(cL, row, note=note, inst=LEADPWM, vol=vol)
        if vib and d >= 4:
            for k in range(2, d): put(cL, row+k, fx=4, param=0x62)
        nxt = mel[i+1][0] + base if i+1 < len(mel) else None
        if nxt is None or nxt > row + d:
            put(cL, row + d, note=OFF)
        if echo:
            er = row + 3
            put(cE, er, note=note, inst=LEADPWM, vol=vol*0.42, fx=8, param=200)
            if nxt is None or nxt + 3 > er + d:
                put(cE, er + d, note=OFF)
        if harmony:
            h = chord_tone_below(note, chord_of_row(r))
            put(cHm, row, note=h, inst=LEADSAW, vol=vol*0.9)
            if vib and d >= 4:
                for k in range(2, d): put(cHm, row+k, fx=4, param=0x42)
            if nxt is None or nxt > row + d:
                put(cHm, row + d, note=OFF)

def bell_line(base, mel, vol=64):
    for i, (r, note, d) in enumerate(mel):
        put(cX, base + r, note=note, inst=BELL, vol=vol)

def drums(base, kind, bar):
    b = base + bar*16
    if kind in ('intro2', 'verse', 'chorus'):
        for r in (0, 4, 8, 12): hit(cK, b+r, KICK, 64)
        if kind == 'verse' and bar in (1, 3): hit(cK, b+14, KICK, 48)
        if kind == 'chorus' and bar == 3: hit(cK, b+14, KICK, 52)
    if kind in ('verse', 'chorus'):
        for r in (4, 12): hit(cS, b+r, SNARE, 64)
    if kind == 'chorus':
        for r in (4, 12): hit(cC, b+r, CLAP, 64)
    if kind == 'intro2':
        for r in (4, 12): hit(cC, b+r, CLAP, 44)
    # hats
    if kind in ('intro2', 'verse', 'chorus'):
        for r in (2, 6, 10, 14):
            if kind == 'chorus' and r == 14 or kind == 'verse' and r == 14 and bar in (1, 3):
                hit(cH, b+r, OHAT, 60)
            else:
                hit(cH, b+r, HAT, 64 if r in (2, 10) else 52)
        if kind == 'chorus':
            for r in (1, 3, 5, 7, 9, 11, 13, 15): hit(cH, b+r, HAT, 22)
    if kind == 'intro1' and bar >= 2:
        for r in (2, 6, 10, 14): hit(cH, b+r, HAT, 30 + 8*(bar-2))
    if kind == 'break':
        hit(cK, b+0, KICK, 60); hit(cK, b+8, KICK, 50)
        if bar >= 2:
            for r in (2, 6, 10, 14): hit(cH, b+r, HAT, 30 + 10*(bar-2))

def fill(base, big):
    """drum fill in rows 56..63 of a section."""
    b = base + 48
    # clear the plain hats/snare in the last half bar first
    for ch in (cS, cH, cC, cK):
        for r in range(b+8, b+16): song[ch].pop(r, None)
    if big:
        hit(cK, b+8, KICK, 64); hit(cK, b+12, KICK, 64); hit(cK, b+14, KICK, 56)
        for r, v in ((8, 40), (10, 46), (12, 52), (13, 56), (14, 60), (15, 64)):
            hit(cS, b+r, SNARE, v)
        put(cS, b+14, fx=0xE, param=0x93); put(cS, b+15, fx=0xE, param=0x93)
        hit(cH, b+10, HAT, 40); hit(cH, b+14, OHAT, 50)
    else:
        hit(cK, b+8, KICK, 64); hit(cK, b+12, KICK, 60)
        for r, v in ((10, 40), (12, 50), (13, 44), (14, 56), (15, 64)):
            hit(cS, b+r, SNARE, v)
        hit(cH, b+10, HAT, 48); hit(cH, b+14, OHAT, 50)

def bass_line(base, chord, bar, style):
    b = base + bar*16
    root = CHORDS[chord][0]
    r2, r3 = NN(root, 2), NN(root, 3)
    if style == 'break':
        put(cB, b, note=r2, inst=BASS, vol=56); put(cB, b+10, note=OFF)
        put(cB, b+12, note=r2, inst=BASS, vol=40); put(cB, b+14, note=OFF)
        return
    pat = [(0, r2, 64), (2, r2, 52), (4, r3, 58), (6, r2, 52), (8, r2, 64), (10, r3, 56), (12, r2, 58), (14, r3, 52)]
    if style == 'chorus':
        pat = [(0, r2, 64), (2, r2, 52), (3, r3, 46), (4, r2, 60), (6, r2, 52), (7, r3, 46),
               (8, r2, 64), (10, r2, 52), (11, r3, 46), (12, r2, 60), (14, r3, 56)]
    for r, n, v in pat:
        put(cB, b+r, note=n, inst=BASS, vol=v)

def arp_line(base, chord, bar, vol=64, variant=0, ch=cA, octave=4, offset=0, accent=True):
    b = base + bar*16
    t = tones(chord)
    seq = [(t[0], 0), (t[1], 0), (t[2], 0), (t[0], 1), (t[1], 1), (t[0], 1), (t[2], 0), (t[1], 0)]
    if variant == 1:
        seq = [(t[0], 0), (t[1], 0), (t[2], 0), (t[0], 1), (t[1], 1), (t[2], 1), (t[1], 1), (t[0], 1)]
    for r in range(16):
        pc, o = seq[r % 8]
        n = NN(pc, octave + o)
        if pc < t[0]: n += 12   # keep tones ascending above root
        v = vol if (r % 4 == 0 or not accent) else vol*0.72
        put(ch, b + r + offset, note=n, inst=PLUCK, vol=v)

def chip_line(base, chord, bar, mode, vol=64):
    b = base + bar*16
    root, iv = CHORDS[chord]
    param = (iv[1] << 4) | iv[2]
    n = NN(root, 4)
    if mode == 'sustain':
        put(cQ, b, note=n, inst=CHIP, vol=vol)
        for r in range(16): put(cQ, b+r, fx=0, param=param)
        put(cQ, b+15, vol=vol*0.6)
    elif mode == 'stab':
        for r in (2, 6, 10, 14):
            put(cQ, b+r, note=n, inst=CHIP, vol=vol, fx=0, param=param)
            put(cQ, b+r+1, fx=0, param=param, vol=vol*0.7)
            if r + 2 < 16: put(cQ, b+r+2, note=OFF)
        put(cQ, b+16, note=OFF) if b + 16 < TOTAL_ROWS else None
    elif mode == 'chorus':
