            put(cQ, base + 56, note=OFF)
            put(cA2, base + 57, note=OFF)
        if name == 'break':
            bell_line(base, parse_mel(BREAK_BELL), 60)
            hit(cX, base + 32, RISER, 60)   # cX also has bell -> bell notes in bars 3-4 will cut riser; avoid:
            # move break bell bars 3-4 to the harmony channel (free in the break)
            for r in range(base + 32, base + 64):
                if r in song[cX] and song[cX][r].get('instrument') == BELL:
                    song[cHm][r] = song[cX].pop(r)
            # build-up snares
            for r, v in ((48, 30), (52, 36), (56, 42), (58, 46), (60, 50), (61, 54), (62, 58), (63, 64)):
                hit(cS, base + r, SNARE, v)
            for r in (48, 56, 60, 62): hit(cK, base + r, KICK, 64)

def emit(path_json, xm_path, wav_path):
    calls = [{"name": "module_new", "arguments": {"channels": NCH, "name": "keygen groove"}}]
    specs = json.load(open('/workspace/work/samples/specs.json'))
    for inst, fname in INSTR_FILES.items():
        s = specs[fname]
        calls.append({"name": "sample_load", "arguments": {"path": f"/workspace/work/samples/{fname}.wav", "instrument": inst}})
        flags = 16 | (1 if s['loop_length'] > 0 else 0)
        calls.append({"name": "sample_set", "arguments": {
            "instrument": inst, "sample": 0, "relative_note": s['relnote'], "finetune": s['finetune'],
            "loop_start": s['loop_start'], "loop_length": s['loop_length'], "flags": flags,
            "volume": int(round(INSTR_VOL[inst] * MIX)), "panning": INSTR_PAN[inst], "name": fname}})
        calls.append({"name": "instrument_set", "arguments": {"instrument": inst, "name": fname}})
    npat = len(SECTIONS)
    for p in range(npat):
        calls.append({"name": "pattern_set_length", "arguments": {"pattern": p, "rows": ROWS}})
    ncells = 0
    for ch in range(NCH):
        for row, cell in sorted(song[ch].items()):
            if row >= TOTAL_ROWS: continue
            p, r = divmod(row, ROWS)
            args = {"pattern": p, "row": r, "channel": ch}
            args.update(cell)
            calls.append({"name": "pattern_set_cell", "arguments": args}); ncells += 1
    for p in range(npat):
        calls.append({"name": "order_set", "arguments": {"position": p, "pattern": p}})
    calls.append({"name": "song_set", "arguments": {"length": npat, "loop_start": RESTART, "bpm": BPM, "speed": SPEED, "name": "keygen groove"}})
    calls.append({"name": "module_save", "arguments": {"path": xm_path}})
    calls.append({"name": "module_render", "arguments": {"path": wav_path}})
    json.dump(calls, open(path_json, 'w'))
    print("cells:", ncells, "calls:", len(calls))

